-- Source: read-only PostgreSQL 17.6 catalogs, 2026-10-20 (Asia/Dhaka).
SET standard_conforming_strings = on;
SET search_path = pg_catalog, public;

CREATE TABLE "public"."notification_preferences" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."notification_preferences_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "user_id" uuid NOT NULL,
  "category" text DEFAULT '*'::text NOT NULL,
  "notification_enabled" boolean DEFAULT true NOT NULL,
  "in_app_enabled" boolean DEFAULT true NOT NULL,
  "toast_enabled" boolean DEFAULT true NOT NULL,
  "system_push_enabled" boolean DEFAULT true NOT NULL,
  "minimum_priority" text DEFAULT 'Low'::text NOT NULL,
  "quiet_hours_enabled" boolean DEFAULT true NOT NULL,
  "quiet_hours_start" time without time zone DEFAULT '22:00:00'::time without time zone NOT NULL,
  "quiet_hours_end" time without time zone DEFAULT '07:00:00'::time without time zone NOT NULL,
  "urgent_bypass_enabled" boolean DEFAULT true NOT NULL,
  "timezone" text DEFAULT 'Asia/Dhaka'::text NOT NULL,
  "default_snooze_minutes" integer DEFAULT 15 NOT NULL,
  "toast_max_visible" integer DEFAULT 2 NOT NULL,
  "toast_gap_seconds" integer DEFAULT 60 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."notification_preferences" OWNER TO "postgres";
COMMENT ON TABLE "public"."notification_preferences" IS 'Per-authenticated-user notification channel, priority, quiet-hours and interaction preferences.';
COMMENT ON COLUMN "public"."notification_preferences"."category" IS 'Notification category. The value * represents the user-wide default preference.';
COMMENT ON COLUMN "public"."notification_preferences"."minimum_priority" IS 'Lowest notification priority enabled for this user and category.';
COMMENT ON COLUMN "public"."notification_preferences"."urgent_bypass_enabled" IS 'Allows Urgent notifications to bypass quiet hours.';
COMMENT ON COLUMN "public"."notification_preferences"."timezone" IS 'IANA timezone used for quiet-hours and reminder calculations.';
